INSERT INTO pdf_insights (id, slug, language, title, subtitle, short_title, content_type, status, author, publication_date, data_period, page_count, reading_time, executive_thesis, short_summary, executive_summary, key_findings, leadership_implications, strategic_questions, methodology, limitations, regions, topics, expertise, keywords, gating_model, pdf_key, original_filename, checksum, mime_type, file_size, version, extraction_confidence, created_by, updated_by, created_at, updated_at) VALUES ('8fa4535e-232e-4001-b4cf-5379b9b5ed24', 'turkiye-ets-pilot-monitoring-plan-8fa4535e', 'en', 'The Türkiye ETS pilot: what the January 2027 monitoring plan deadline asks of your plant', 'The pilot procedures approved on 30 September 2026 make 2026 a reporting year and 2027 the first year with allowances to surrender. The first step is a monitoring methodology plan.', 'The Türkiye ETS pilot', 'Strategic Perspective', 'review_required', 'Ahmed Furkan Gul', '2026-10-26', 'October 2026', 5, 15, 'The pilot procedures approved on 30 September 2026 make 2026 a reporting year and 2027 the first year with allowances to surrender. The first step is a monitoring methodology plan.', 'On 30 September 2026 the Presidency of Climate Change approved the procedures and principles for the pilot phase of the Türkiye Emissions Trading System. The pilot covers the 2026 and 2027 system years and category B and C installations, those emitting more than 50,000 tonnes of CO2 equivalent a year, in electricity generation, cement, iron and steel, aluminium and fertilisers.', 'On 30 September 2026 the Presidency of Climate Change approved the procedures and principles for the pilot phase of the Türkiye Emissions Trading System. The pilot covers the 2026 and 2027 system years and category B and C installations, those emitting more than 50,000 tonnes of CO2 equivalent a year, in electricity generation, cement, iron and steel, aluminium and fertilisers. 2026 is a reporting year. Allowances are first surrendered for 2027 emissions, with free allocation in 2027 set at 100% of the benchmark-based allocation. That first surrender falls due on the last business day of November 2028. The nearest deadline is the monitoring methodology plan. On 13 October 2026 the Presidency extended the deadline for the first plans from 27 October 2026 to 27 January 2027. The plan defines the installation’s sub-installations and how their activity levels are monitored, and so the data on which free allocation will be calculated.', '[{"title": "A pilot with five sectors", "explanation": "On 30 September 2026 the Presidency of Climate Change approved the procedures and principles for the pilot phase of the Türkiye Emissions Trading System. The pilot covers the 2026 and 2027 system years and category B and C installations, those emitting more than 50,000 tonnes of CO2 equivalent a year, in electricity generation, cement, iron and steel, aluminium and fertilisers.", "page": 2}, {"title": "The plan decides allocation data", "explanation": "2026 is a reporting year. Allowances are first surrendered for 2027 emissions, with free allocation in 2027 set at 100% of the benchmark-based allocation. That first surrender falls due on the last business day of November 2028.", "page": 2}, {"title": "Benchmarks, not actual emissions", "explanation": "The nearest deadline is the monitoring methodology plan. On 13 October 2026 the Presidency extended the deadline for the first plans from 27 October 2026 to 27 January 2027. The plan defines the installation’s sub-installations and how their activity levels are monitored, and so the data on which free allocation will be calculated.", "page": 2}]', '[]', '["Which of our installations are in the pilot, and in which category?", "Who is preparing our monitoring methodology plan for 27 January 2027, and has the sub-installation split been agreed with the plant?", "Do our meters and records support activity levels per sub-installation for the whole of 2026?", "Which accredited verifier will check our 2026 activity level report, and when?", "How does our emission intensity compare with what the benchmark is likely to be?", "What would a shortfall in 2027 cost at a range of allowance prices?", "Does the same data serve the CBAM requests from our EU buyers?"]', 'Desk review of official EU sources checked on 26 October 2026, combined with Ganrich Advisory’s October 2026 review of opportunities in Türkiye.', 'General information, not legal, customs, tax or engineering advice. Rules and dates change; confirm against official sources. No client work or results are described.', '["Türkiye", "European Union"]', '["Türkiye ETS", "Carbon", "Industrial plants"]', '["Operating model"]', '["Türkiye ETS", "ETS pilot", "monitoring methodology plan", "free allocation", "benchmarks", "CBAM"]', 'fully_ungated', 'pdf-insights/8fa4535e-232e-4001-b4cf-5379b9b5ed24/v1/Ganrich-Turkiye-ETS-Pilot-EN.pdf', 'Ganrich-Turkiye-ETS-Pilot-EN.pdf', 'e01c8ef28d4ef6b6900a32829500abd591f5983a41a89bc534c239de79ff0309', 'application/pdf', 265473, 1, 'reviewed', 'furkangul@ganrichadvisory.com', 'furkangul@ganrichadvisory.com', '2026-10-26T08:00:00.000Z', '2026-10-26T08:00:00.000Z');
INSERT INTO pdf_insight_versions (id, insight_id, version, r2_key, filename, checksum, file_size, uploaded_by, uploaded_at, status) VALUES ('1b7f0d0e-1a40-4c55-9c71-000000000029', '8fa4535e-232e-4001-b4cf-5379b9b5ed24', 1, 'pdf-insights/8fa4535e-232e-4001-b4cf-5379b9b5ed24/v1/Ganrich-Turkiye-ETS-Pilot-EN.pdf', 'Ganrich-Turkiye-ETS-Pilot-EN.pdf', 'e01c8ef28d4ef6b6900a32829500abd591f5983a41a89bc534c239de79ff0309', 265473, 'furkangul@ganrichadvisory.com', '2026-10-26T08:00:00.000Z', 'current');
INSERT INTO pdf_insights (id, slug, language, title, subtitle, short_title, content_type, status, author, publication_date, data_period, page_count, reading_time, executive_thesis, short_summary, executive_summary, key_findings, leadership_implications, strategic_questions, methodology, limitations, regions, topics, expertise, keywords, gating_model, pdf_key, original_filename, checksum, mime_type, file_size, version, extraction_confidence, created_by, updated_by, created_at, updated_at) VALUES ('204bc82e-5d15-4b9e-bb40-661175f35c47', 'eudr-checklist-turkish-wood-furniture-204bc82e', 'en', 'EUDR from 30 December 2026: a checklist for Turkish wood and furniture exporters', 'The amended Deforestation Regulation applies on schedule. Your EU importer files the statement, but the data has to come from you.', 'EUDR from 30 December 2026', 'Strategic Perspective', 'review_required', 'Ahmed Furkan Gul', '2026-10-26', 'October 2026', 5, 15, 'The amended Deforestation Regulation applies on schedule. Your EU importer files the statement, but the data has to come from you.', 'The EU Deforestation Regulation (EUDR), Regulation (EU) 2023/1115, applies from 30 December 2026 to large and medium operators and traders, and to micro and small operators of timber products already covered by the EU Timber Regulation. Other micro and small operators follow on 30 June 2027. The Commission’s simplification review of 4 May 2026 concluded that the basic text should not be changed again.', 'The EU Deforestation Regulation (EUDR), Regulation (EU) 2023/1115, applies from 30 December 2026 to large and medium operators and traders, and to micro and small operators of timber products already covered by the EU Timber Regulation. Other micro and small operators follow on 30 June 2027. The Commission’s simplification review of 4 May 2026 concluded that the basic text should not be changed again. The due diligence statement is filed by the operator that places the product on the EU market, usually your importer. As a Turkish exporter you file nothing, but your importer cannot file without the country of production, the geolocation of every plot where the wood was harvested, quantities, supplier details and evidence that the harvest was legal. The 2025 amendment mainly eased obligations further down the EU supply chain. For a Turkish exporter, the data request from the first EU importer is unchanged, and it concerns the wood itself: where it was grown, not where the furniture was made.', '[{"title": "The dates are fixed", "explanation": "The EU Deforestation Regulation (EUDR), Regulation (EU) 2023/1115, applies from 30 December 2026 to large and medium operators and traders, and to micro and small operators of timber products already covered by the EU Timber Regulation. Other micro and small operators follow on 30 June 2027. The Commission’s simplification review of 4 May 2026 concluded that the basic text should not be changed again.", "page": 2}, {"title": "The importer files, you supply", "explanation": "The due diligence statement is filed by the operator that places the product on the EU market, usually your importer. As a Turkish exporter you file nothing, but your importer cannot file without the country of production, the geolocation of every plot where the wood was harvested, quantities, supplier details and evidence that the harvest was legal.", "page": 2}, {"title": "It is about where the wood grew", "explanation": "The 2025 amendment mainly eased obligations further down the EU supply chain. For a Turkish exporter, the data request from the first EU importer is unchanged, and it concerns the wood itself: where it was grown, not where the furniture was made.", "page": 2}]', '[]', '["Which of our EU product lines are in scope under the current Annex I?", "For each wood input, do we know the country of harvest and the plot geolocation?", "Which suppliers and traders cannot provide geolocation, and what share of volume do they represent?", "Can we keep wood of known origin separate from other wood through production?", "What has each of our EU importers asked for, in which format and by when?", "Who in the company owns the EUDR data package for each shipment?", "Which of our importers are micro or small timber operators that must comply from 30 December 2026?"]', 'Desk review of official EU sources checked on 26 October 2026, combined with Ganrich Advisory’s October 2026 review of opportunities in Türkiye.', 'General information, not legal, customs, tax or engineering advice. Rules and dates change; confirm against official sources. No client work or results are described.', '["Türkiye", "European Union"]', '["EUDR", "Deforestation", "EU market access"]', '["Operating model"]', '["EUDR", "deforestation", "geolocation", "due diligence statement", "wood", "furniture"]', 'fully_ungated', 'pdf-insights/204bc82e-5d15-4b9e-bb40-661175f35c47/v1/Ganrich-EUDR-Checklist-EN.pdf', 'Ganrich-EUDR-Checklist-EN.pdf', '3fc6305f937ef1b00883608a73193b0c10d761bca5480dd8e6e5bc2d4b6eff10', 'application/pdf', 261620, 1, 'reviewed', 'furkangul@ganrichadvisory.com', 'furkangul@ganrichadvisory.com', '2026-10-26T08:00:00.000Z', '2026-10-26T08:00:00.000Z');
INSERT INTO pdf_insight_versions (id, insight_id, version, r2_key, filename, checksum, file_size, uploaded_by, uploaded_at, status) VALUES ('1b7f0d0e-1a40-4c55-9c71-000000000030', '204bc82e-5d15-4b9e-bb40-661175f35c47', 1, 'pdf-insights/204bc82e-5d15-4b9e-bb40-661175f35c47/v1/Ganrich-EUDR-Checklist-EN.pdf', 'Ganrich-EUDR-Checklist-EN.pdf', '3fc6305f937ef1b00883608a73193b0c10d761bca5480dd8e6e5bc2d4b6eff10', 261620, 'furkangul@ganrichadvisory.com', '2026-10-26T08:00:00.000Z', 'current');
INSERT INTO pdf_insights (id, slug, language, title, subtitle, short_title, content_type, status, author, publication_date, data_period, page_count, reading_time, executive_thesis, short_summary, executive_summary, key_findings, leadership_implications, strategic_questions, methodology, limitations, regions, topics, expertise, keywords, gating_model, pdf_key, original_filename, checksum, mime_type, file_size, version, extraction_confidence, created_by, updated_by, created_at, updated_at) VALUES ('eb264118-eebc-4198-9641-04b6d2bf31a6', 'textile-product-passport-turkish-suppliers-eb264118', 'en', 'The textile product passport: what is decided, what is not, and what Turkish suppliers can prepare now', 'The EU framework for digital product passports is in force. The textile rules are not yet written, but EU buyers are already asking for the data.', 'The textile product passport', 'Strategic Perspective', 'review_required', 'Ahmed Furkan Gul', '2026-10-26', 'October 2026', 5, 15, 'The EU framework for digital product passports is in force. The textile rules are not yet written, but EU buyers are already asking for the data.', 'The Ecodesign for Sustainable Products Regulation (ESPR), Regulation (EU) 2024/1781, has applied since July 2024. It sets the framework for digital product passports, and the EU registry for passport identifiers was due by 19 July 2026. Textiles and apparel are a priority product group in the Commission’s ESPR working plan, with a delegated act planned for 2027.', 'The Ecodesign for Sustainable Products Regulation (ESPR), Regulation (EU) 2024/1781, has applied since July 2024. It sets the framework for digital product passports, and the EU registry for passport identifiers was due by 19 July 2026. Textiles and apparel are a priority product group in the Commission’s ESPR working plan, with a delegated act planned for 2027. Requirements in a product act apply no earlier than 18 months after it enters into force, so a mandatory textile passport is unlikely before 2029. Other parts of ESPR already apply: since 19 July 2026 large companies may not destroy unsold apparel, clothing accessories and footwear in the EU. The textile act will decide which data fields, data carrier and level of detail are required. The likely content is already visible: product identification, fibre composition, origin, the companies involved, care and repair, and end-of-life information. Most of it sits with the supplier, often with subcontractors.', '[{"title": "The framework is in force", "explanation": "The Ecodesign for Sustainable Products Regulation (ESPR), Regulation (EU) 2024/1781, has applied since July 2024. It sets the framework for digital product passports, and the EU registry for passport identifiers was due by 19 July 2026. Textiles and apparel are a priority product group in the Commission’s ESPR working plan, with a delegated act planned for 2027.", "page": 2}, {"title": "The textile act comes first", "explanation": "Requirements in a product act apply no earlier than 18 months after it enters into force, so a mandatory textile passport is unlikely before 2029. Other parts of ESPR already apply: since 19 July 2026 large companies may not destroy unsold apparel, clothing accessories and footwear in the EU.", "page": 2}, {"title": "The data sits with suppliers", "explanation": "The textile act will decide which data fields, data carrier and level of detail are required. The likely content is already visible: product identification, fibre composition, origin, the companies involved, care and repair, and end-of-life information. Most of it sits with the supplier, often with subcontractors.", "page": 2}]', '[]', '["Which of our EU customers have asked for fibre, origin or processing data per model, and in what format?", "Do we hold processing-step data for subcontracted dyeing, printing and finishing?", "Can we produce a model-level record with fibre composition, origin and care information for our main lines?", "Are our product identifiers consistent with those our EU customers use?", "How have large EU buyers changed order sizes and replenishment since July 2026?", "Could one data structure answer passport, forced labour and chemicals requests?", "Who owns product data in the company?"]', 'Desk review of official EU sources checked on 26 October 2026, combined with Ganrich Advisory’s October 2026 review of opportunities in Türkiye.', 'General information, not legal, customs, tax or engineering advice. Rules and dates change; confirm against official sources. No client work or results are described.', '["Türkiye", "European Union"]', '["ESPR", "Textiles and apparel", "EU market access"]', '["Operating model"]', '["ESPR", "digital product passport", "textiles", "destruction ban", "traceability"]', 'fully_ungated', 'pdf-insights/eb264118-eebc-4198-9641-04b6d2bf31a6/v1/Ganrich-Textile-Product-Passport-EN.pdf', 'Ganrich-Textile-Product-Passport-EN.pdf', 'a9afddb82952f8eb5b81548cd1104c293745214b8a8f1f73728df181bf860c08', 'application/pdf', 261432, 1, 'reviewed', 'furkangul@ganrichadvisory.com', 'furkangul@ganrichadvisory.com', '2026-10-26T08:00:00.000Z', '2026-10-26T08:00:00.000Z');
INSERT INTO pdf_insight_versions (id, insight_id, version, r2_key, filename, checksum, file_size, uploaded_by, uploaded_at, status) VALUES ('1b7f0d0e-1a40-4c55-9c71-000000000031', 'eb264118-eebc-4198-9641-04b6d2bf31a6', 1, 'pdf-insights/eb264118-eebc-4198-9641-04b6d2bf31a6/v1/Ganrich-Textile-Product-Passport-EN.pdf', 'Ganrich-Textile-Product-Passport-EN.pdf', 'a9afddb82952f8eb5b81548cd1104c293745214b8a8f1f73728df181bf860c08', 261432, 'furkangul@ganrichadvisory.com', '2026-10-26T08:00:00.000Z', 'current');
INSERT INTO pdf_insights (id, slug, language, title, subtitle, short_title, content_type, status, author, publication_date, data_period, page_count, reading_time, executive_thesis, short_summary, executive_summary, key_findings, leadership_implications, strategic_questions, methodology, limitations, regions, topics, expertise, keywords, gating_model, pdf_key, original_filename, checksum, mime_type, file_size, version, extraction_confidence, created_by, updated_by, created_at, updated_at) VALUES ('98334c09-d314-43c5-8221-72801628c76b', 'turkiye-ets-pilotu-izleme-plani-98334c09', 'tr', 'Türkiye ETS pilotu: Ocak 2027 izleme planı son tarihi tesisinizden ne istiyor?', '30 Eylül 2026’da onaylanan pilot usul ve esaslarına göre 2026 raporlama yılı, 2027 ise emisyon izinlerinin ilk kez teslim edileceği yıl. İlk adım İzleme Metodolojisi Planı.', 'Türkiye ETS pilotu', 'Strategic Perspective', 'review_required', 'Ahmed Furkan Gül', '2026-10-26', 'Ekim 2026', 5, 15, '30 Eylül 2026’da onaylanan pilot usul ve esaslarına göre 2026 raporlama yılı, 2027 ise emisyon izinlerinin ilk kez teslim edileceği yıl. İlk adım İzleme Metodolojisi Planı.', 'İklim Değişikliği Başkanlığı, Türkiye Emisyon Ticaret Sistemi’nin pilot dönemine ilişkin usul ve esasları 30 Eylül 2026’da onayladı. Pilot, 2026 ve 2027 sistem yıllarını ve elektrik üretimi, çimento, demir-çelik, alüminyum ve gübre sektörlerinde yıllık 50.000 ton CO2 eşdeğerinin üzerinde emisyonu olan B ve C kategorisi tesisleri kapsıyor.', 'İklim Değişikliği Başkanlığı, Türkiye Emisyon Ticaret Sistemi’nin pilot dönemine ilişkin usul ve esasları 30 Eylül 2026’da onayladı. Pilot, 2026 ve 2027 sistem yıllarını ve elektrik üretimi, çimento, demir-çelik, alüminyum ve gübre sektörlerinde yıllık 50.000 ton CO2 eşdeğerinin üzerinde emisyonu olan B ve C kategorisi tesisleri kapsıyor. 2026 raporlama yılı. Emisyon izinleri ilk kez 2027 emisyonları için teslim ediliyor; 2027’de ücretsiz tahsis, referans değere dayalı tahsisin %100’ü olarak belirlendi. Bu ilk teslimin son günü Kasım 2028’in son iş günü. En yakın son tarih İzleme Metodolojisi Planı. Başkanlık 13 Ekim 2026’da ilk planların sunulma süresini 27 Ekim 2026’dan 27 Ocak 2027’ye uzattı. Plan, tesisin alt tesislerini ve bunların faaliyet seviyelerinin nasıl izleneceğini, dolayısıyla ücretsiz tahsisin hesaplanacağı veriyi belirliyor.', '[{"title": "Beş sektörlü bir pilot", "explanation": "İklim Değişikliği Başkanlığı, Türkiye Emisyon Ticaret Sistemi’nin pilot dönemine ilişkin usul ve esasları 30 Eylül 2026’da onayladı. Pilot, 2026 ve 2027 sistem yıllarını ve elektrik üretimi, çimento, demir-çelik, alüminyum ve gübre sektörlerinde yıllık 50.000 ton CO2 eşdeğerinin üzerinde emisyonu olan B ve C kategorisi tesisleri kapsıyor.", "page": 2}, {"title": "Plan, tahsis verisini belirliyor", "explanation": "2026 raporlama yılı. Emisyon izinleri ilk kez 2027 emisyonları için teslim ediliyor; 2027’de ücretsiz tahsis, referans değere dayalı tahsisin %100’ü olarak belirlendi. Bu ilk teslimin son günü Kasım 2028’in son iş günü.", "page": 2}, {"title": "Gerçek emisyon değil, referans değer", "explanation": "En yakın son tarih İzleme Metodolojisi Planı. Başkanlık 13 Ekim 2026’da ilk planların sunulma süresini 27 Ekim 2026’dan 27 Ocak 2027’ye uzattı. Plan, tesisin alt tesislerini ve bunların faaliyet seviyelerinin nasıl izleneceğini, dolayısıyla ücretsiz tahsisin hesaplanacağı veriyi belirliyor.", "page": 2}]', '[]', '["Tesislerimizden hangileri pilotta ve hangi kategoride?", "27 Ocak 2027 için İzleme Metodolojisi Planımızı kim hazırlıyor; alt tesis ayrımı tesisle birlikte netleştirildi mi?", "Sayaçlarımız ve kayıtlarımız 2026’nın tamamı için alt tesis bazında faaliyet seviyesini destekliyor mu?", "2026 faaliyet seviyesi raporumuzu hangi akredite doğrulayıcı, ne zaman kontrol edecek?", "Emisyon yoğunluğumuz olası referans değerle nasıl karşılaştırılıyor?", "2027’deki olası bir izin açığı, farklı fiyat varsayımlarında bize neye mal olur?", "Aynı veri AB alıcılarımızın SKDM taleplerini de karşılıyor mu?"]', '26 Ekim 2026’da kontrol edilen resmî AB kaynaklarının masa başı incelemesi ile Ganrich Advisory’nin Ekim 2026 Türkiye fırsat incelemesinin birleşimi.', 'Genel bilgi niteliğindedir; hukuki, gümrük, vergi veya mühendislik danışmanlığı değildir. Kurallar ve tarihler değişebilir; resmî kaynaklardan teyit edin. Müşteri çalışması veya sonucu anlatılmaz.', '["Türkiye", "European Union"]', '["Türkiye ETS", "Carbon", "Industrial plants"]', '["Operating model"]', '["Türkiye ETS", "ETS pilot", "monitoring methodology plan", "free allocation", "benchmarks", "CBAM"]', 'fully_ungated', 'pdf-insights/98334c09-d314-43c5-8221-72801628c76b/v1/Ganrich-Turkiye-ETS-Pilot-TR.pdf', 'Ganrich-Turkiye-ETS-Pilot-TR.pdf', '38c6af30c0f3eeb8436809679b643263e7f86065e5f5abee8323bb5f80af8725', 'application/pdf', 275160, 1, 'reviewed', 'furkangul@ganrichadvisory.com', 'furkangul@ganrichadvisory.com', '2026-10-26T08:00:00.000Z', '2026-10-26T08:00:00.000Z');
INSERT INTO pdf_insight_versions (id, insight_id, version, r2_key, filename, checksum, file_size, uploaded_by, uploaded_at, status) VALUES ('1b7f0d0e-1a40-4c55-9c71-000000000032', '98334c09-d314-43c5-8221-72801628c76b', 1, 'pdf-insights/98334c09-d314-43c5-8221-72801628c76b/v1/Ganrich-Turkiye-ETS-Pilot-TR.pdf', 'Ganrich-Turkiye-ETS-Pilot-TR.pdf', '38c6af30c0f3eeb8436809679b643263e7f86065e5f5abee8323bb5f80af8725', 275160, 'furkangul@ganrichadvisory.com', '2026-10-26T08:00:00.000Z', 'current');
INSERT INTO pdf_insights (id, slug, language, title, subtitle, short_title, content_type, status, author, publication_date, data_period, page_count, reading_time, executive_thesis, short_summary, executive_summary, key_findings, leadership_implications, strategic_questions, methodology, limitations, regions, topics, expertise, keywords, gating_model, pdf_key, original_filename, checksum, mime_type, file_size, version, extraction_confidence, created_by, updated_by, created_at, updated_at) VALUES ('a607fc4b-0728-49b3-bf41-c1b49e304895', 'eudr-kontrol-listesi-ahsap-mobilya-a607fc4b', 'tr', '30 Aralık 2026’dan itibaren EUDR: Türk ahşap ve mobilya ihracatçıları için kontrol listesi', 'Değiştirilen Ormansızlaşma Yönetmeliği takvimine uygun olarak uygulanıyor. Beyanı AB’deki ithalatçınız veriyor, ama veri sizden gelmek zorunda.', '30 Aralık 2026’dan itibaren EUDR', 'Strategic Perspective', 'review_required', 'Ahmed Furkan Gül', '2026-10-26', 'Ekim 2026', 5, 15, 'Değiştirilen Ormansızlaşma Yönetmeliği takvimine uygun olarak uygulanıyor. Beyanı AB’deki ithalatçınız veriyor, ama veri sizden gelmek zorunda.', 'AB Ormansızlaşma Yönetmeliği (EUDR), (AB) 2023/1115 sayılı Tüzük, 30 Aralık 2026’dan itibaren büyük ve orta ölçekli işletmecilere ve tüccarlara, ayrıca AB Kereste Tüzüğü kapsamındaki ahşap ürünlerini piyasaya süren mikro ve küçük işletmecilere uygulanıyor. Diğer mikro ve küçük işletmeciler 30 Haziran 2027’de takip ediyor. Komisyon 4 Mayıs 2026 tarihli sadeleştirme incelemesinde temel metnin yeniden değiştirilmemesi gerektiği sonucuna vardı.', 'AB Ormansızlaşma Yönetmeliği (EUDR), (AB) 2023/1115 sayılı Tüzük, 30 Aralık 2026’dan itibaren büyük ve orta ölçekli işletmecilere ve tüccarlara, ayrıca AB Kereste Tüzüğü kapsamındaki ahşap ürünlerini piyasaya süren mikro ve küçük işletmecilere uygulanıyor. Diğer mikro ve küçük işletmeciler 30 Haziran 2027’de takip ediyor. Komisyon 4 Mayıs 2026 tarihli sadeleştirme incelemesinde temel metnin yeniden değiştirilmemesi gerektiği sonucuna vardı. Durum tespiti beyanını ürünü AB pazarına süren işletmeci, yani genellikle ithalatçınız verir. Türk ihracatçı olarak siz beyan vermezsiniz; ancak ithalatçınız üretim ülkesi, ahşabın kesildiği her arazi parçasının coğrafi konumu, miktarlar, tedarikçi bilgileri ve kesimin yasal olduğunu gösteren kanıtlar olmadan beyan veremez. 2025 değişikliği esas olarak AB tedarik zincirinin aşağısındaki yükümlülükleri hafifletti. Türk ihracatçı için ilk AB ithalatçısının veri talebi değişmedi ve bu talep ahşabın kendisiyle ilgili: mobilyanın nerede üretildiği değil, ağacın nerede yetiştiği.', '[{"title": "Tarihler kesinleşti", "explanation": "AB Ormansızlaşma Yönetmeliği (EUDR), (AB) 2023/1115 sayılı Tüzük, 30 Aralık 2026’dan itibaren büyük ve orta ölçekli işletmecilere ve tüccarlara, ayrıca AB Kereste Tüzüğü kapsamındaki ahşap ürünlerini piyasaya süren mikro ve küçük işletmecilere uygulanıyor. Diğer mikro ve küçük işletmeciler 30 Haziran 2027’de takip ediyor. Komisyon 4 Mayıs 2026 tarihli sadeleştirme incelemesinde temel metnin yeniden değiştirilmemesi gerektiği sonucuna vardı.", "page": 2}, {"title": "Beyanı ithalatçı verir, veriyi siz sağlarsınız", "explanation": "Durum tespiti beyanını ürünü AB pazarına süren işletmeci, yani genellikle ithalatçınız verir. Türk ihracatçı olarak siz beyan vermezsiniz; ancak ithalatçınız üretim ülkesi, ahşabın kesildiği her arazi parçasının coğrafi konumu, miktarlar, tedarikçi bilgileri ve kesimin yasal olduğunu gösteren kanıtlar olmadan beyan veremez.", "page": 2}, {"title": "Belirleyici olan ağacın yetiştiği yer", "explanation": "2025 değişikliği esas olarak AB tedarik zincirinin aşağısındaki yükümlülükleri hafifletti. Türk ihracatçı için ilk AB ithalatçısının veri talebi değişmedi ve bu talep ahşabın kendisiyle ilgili: mobilyanın nerede üretildiği değil, ağacın nerede yetiştiği.", "page": 2}]', '[]', '["AB’ye sattığımız ürün gruplarından hangileri güncel I. Ek’e göre kapsamda?", "Her ahşap girdisi için kesim ülkesini ve arazi koordinatlarını biliyor muyuz?", "Hangi tedarikçi ve tüccarlar coğrafi konum veremiyor ve hacmimizin ne kadarını oluşturuyorlar?", "Menşei bilinen ahşabı üretim boyunca diğer ahşaptan ayrı tutabiliyor muyuz?", "AB ithalatçılarımızın her biri ne istedi, hangi formatta ve ne zamana kadar?", "Her sevkiyatın EUDR veri paketinden şirkette kim sorumlu?", "İthalatçılarımızdan hangileri 30 Aralık 2026’dan itibaren uyması gereken mikro veya küçük ahşap işletmecisi?"]', '26 Ekim 2026’da kontrol edilen resmî AB kaynaklarının masa başı incelemesi ile Ganrich Advisory’nin Ekim 2026 Türkiye fırsat incelemesinin birleşimi.', 'Genel bilgi niteliğindedir; hukuki, gümrük, vergi veya mühendislik danışmanlığı değildir. Kurallar ve tarihler değişebilir; resmî kaynaklardan teyit edin. Müşteri çalışması veya sonucu anlatılmaz.', '["Türkiye", "European Union"]', '["EUDR", "Deforestation", "EU market access"]', '["Operating model"]', '["EUDR", "deforestation", "geolocation", "due diligence statement", "wood", "furniture"]', 'fully_ungated', 'pdf-insights/a607fc4b-0728-49b3-bf41-c1b49e304895/v1/Ganrich-EUDR-Kontrol-Listesi-TR.pdf', 'Ganrich-EUDR-Kontrol-Listesi-TR.pdf', '36a6a55d08ec9dfaf4cf8b2c8800928c208bb5f1a1ecf831c801b0fda98d4a52', 'application/pdf', 276438, 1, 'reviewed', 'furkangul@ganrichadvisory.com', 'furkangul@ganrichadvisory.com', '2026-10-26T08:00:00.000Z', '2026-10-26T08:00:00.000Z');
INSERT INTO pdf_insight_versions (id, insight_id, version, r2_key, filename, checksum, file_size, uploaded_by, uploaded_at, status) VALUES ('1b7f0d0e-1a40-4c55-9c71-000000000033', 'a607fc4b-0728-49b3-bf41-c1b49e304895', 1, 'pdf-insights/a607fc4b-0728-49b3-bf41-c1b49e304895/v1/Ganrich-EUDR-Kontrol-Listesi-TR.pdf', 'Ganrich-EUDR-Kontrol-Listesi-TR.pdf', '36a6a55d08ec9dfaf4cf8b2c8800928c208bb5f1a1ecf831c801b0fda98d4a52', 276438, 'furkangul@ganrichadvisory.com', '2026-10-26T08:00:00.000Z', 'current');
INSERT INTO pdf_insights (id, slug, language, title, subtitle, short_title, content_type, status, author, publication_date, data_period, page_count, reading_time, executive_thesis, short_summary, executive_summary, key_findings, leadership_implications, strategic_questions, methodology, limitations, regions, topics, expertise, keywords, gating_model, pdf_key, original_filename, checksum, mime_type, file_size, version, extraction_confidence, created_by, updated_by, created_at, updated_at) VALUES ('66a3e53c-2fcf-43be-b700-2992a2dcf1f1', 'tekstil-urun-pasaportu-turk-tedarikci-66a3e53c', 'tr', 'Tekstilde dijital ürün pasaportu: ne kesinleşti, ne belirsiz, Türk tedarikçiler şimdi neyi hazırlayabilir?', 'Dijital ürün pasaportu için AB çerçevesi yürürlükte. Tekstil kuralları henüz yazılmadı, ama AB alıcıları veriyi şimdiden istiyor.', 'Tekstilde dijital ürün pasaportu', 'Strategic Perspective', 'review_required', 'Ahmed Furkan Gül', '2026-10-26', 'Ekim 2026', 5, 15, 'Dijital ürün pasaportu için AB çerçevesi yürürlükte. Tekstil kuralları henüz yazılmadı, ama AB alıcıları veriyi şimdiden istiyor.', 'Sürdürülebilir Ürünler için Ekotasarım Tüzüğü (ESPR), (AB) 2024/1781 sayılı Tüzük, Temmuz 2024’ten beri yürürlükte. Dijital ürün pasaportunun çerçevesini çiziyor; pasaport tanımlayıcıları için AB sicilinin 19 Temmuz 2026’ya kadar kurulması gerekiyordu. Tekstil ve hazır giyim, Komisyon’un ESPR çalışma planında öncelikli ürün grubu ve yetki devrine dayalı tüzüğün 2027’de çıkarılması planlanıyor.', 'Sürdürülebilir Ürünler için Ekotasarım Tüzüğü (ESPR), (AB) 2024/1781 sayılı Tüzük, Temmuz 2024’ten beri yürürlükte. Dijital ürün pasaportunun çerçevesini çiziyor; pasaport tanımlayıcıları için AB sicilinin 19 Temmuz 2026’ya kadar kurulması gerekiyordu. Tekstil ve hazır giyim, Komisyon’un ESPR çalışma planında öncelikli ürün grubu ve yetki devrine dayalı tüzüğün 2027’de çıkarılması planlanıyor. Bir ürün tüzüğündeki gereklilikler, tüzüğün yürürlüğe girmesinden en erken 18 ay sonra uygulanıyor; bu yüzden zorunlu tekstil pasaportunun 2029’dan önce gelmesi beklenmiyor. ESPR’nin diğer bölümleri ise şimdiden uygulanıyor: 19 Temmuz 2026’dan beri büyük şirketler AB’de satılmayan giyim ürünlerini, giyim aksesuarlarını ve ayakkabıları imha edemiyor. Hangi veri alanlarının, hangi veri taşıyıcının ve hangi ayrıntı düzeyinin gerekeceğine tekstil tüzüğü karar verecek. Olası içerik şimdiden görünüyor: ürün kimliği, lif bileşimi, menşe, sürece katılan şirketler, bakım ve onarım ile ömür sonu bilgileri. Bu verinin büyük kısmı tedarikçide, çoğu zaman da fasoncularda.', '[{"title": "Çerçeve yürürlükte", "explanation": "Sürdürülebilir Ürünler için Ekotasarım Tüzüğü (ESPR), (AB) 2024/1781 sayılı Tüzük, Temmuz 2024’ten beri yürürlükte. Dijital ürün pasaportunun çerçevesini çiziyor; pasaport tanımlayıcıları için AB sicilinin 19 Temmuz 2026’ya kadar kurulması gerekiyordu. Tekstil ve hazır giyim, Komisyon’un ESPR çalışma planında öncelikli ürün grubu ve yetki devrine dayalı tüzüğün 2027’de çıkarılması planlanıyor.", "page": 2}, {"title": "Önce tekstil tüzüğü gelecek", "explanation": "Bir ürün tüzüğündeki gereklilikler, tüzüğün yürürlüğe girmesinden en erken 18 ay sonra uygulanıyor; bu yüzden zorunlu tekstil pasaportunun 2029’dan önce gelmesi beklenmiyor. ESPR’nin diğer bölümleri ise şimdiden uygulanıyor: 19 Temmuz 2026’dan beri büyük şirketler AB’de satılmayan giyim ürünlerini, giyim aksesuarlarını ve ayakkabıları imha edemiyor.", "page": 2}, {"title": "Veri tedarikçide", "explanation": "Hangi veri alanlarının, hangi veri taşıyıcının ve hangi ayrıntı düzeyinin gerekeceğine tekstil tüzüğü karar verecek. Olası içerik şimdiden görünüyor: ürün kimliği, lif bileşimi, menşe, sürece katılan şirketler, bakım ve onarım ile ömür sonu bilgileri. Bu verinin büyük kısmı tedarikçide, çoğu zaman da fasoncularda.", "page": 2}]', '[]', '["AB müşterilerimizden hangileri model bazında lif, menşe veya işlem verisi istedi, hangi formatta?", "Fason yaptırdığımız boya, baskı ve apre için işlem adımı verisine sahip miyiz?", "Ana ürün gruplarımız için lif bileşimi, menşe ve bakım bilgisini içeren model bazında bir kayıt üretebiliyor muyuz?", "Ürün tanımlayıcılarımız AB müşterilerimizin kullandıklarıyla tutarlı mı?", "Büyük AB alıcıları Temmuz 2026’dan beri sipariş büyüklüklerini ve tamamlama siparişlerini nasıl değiştirdi?", "Tek bir veri yapısı pasaport, zorla çalıştırma ve kimyasal taleplerini karşılayabilir mi?", "Şirkette ürün verisinden kim sorumlu?"]', '26 Ekim 2026’da kontrol edilen resmî AB kaynaklarının masa başı incelemesi ile Ganrich Advisory’nin Ekim 2026 Türkiye fırsat incelemesinin birleşimi.', 'Genel bilgi niteliğindedir; hukuki, gümrük, vergi veya mühendislik danışmanlığı değildir. Kurallar ve tarihler değişebilir; resmî kaynaklardan teyit edin. Müşteri çalışması veya sonucu anlatılmaz.', '["Türkiye", "European Union"]', '["ESPR", "Textiles and apparel", "EU market access"]', '["Operating model"]', '["ESPR", "digital product passport", "textiles", "destruction ban", "traceability"]', 'fully_ungated', 'pdf-insights/66a3e53c-2fcf-43be-b700-2992a2dcf1f1/v1/Ganrich-Tekstil-Urun-Pasaportu-TR.pdf', 'Ganrich-Tekstil-Urun-Pasaportu-TR.pdf', 'bcbcd9282d25f5407974187031f4b0beb2a2f65e3033be08034cdbb48e9337c3', 'application/pdf', 272944, 1, 'reviewed', 'furkangul@ganrichadvisory.com', 'furkangul@ganrichadvisory.com', '2026-10-26T08:00:00.000Z', '2026-10-26T08:00:00.000Z');
INSERT INTO pdf_insight_versions (id, insight_id, version, r2_key, filename, checksum, file_size, uploaded_by, uploaded_at, status) VALUES ('1b7f0d0e-1a40-4c55-9c71-000000000034', '66a3e53c-2fcf-43be-b700-2992a2dcf1f1', 1, 'pdf-insights/66a3e53c-2fcf-43be-b700-2992a2dcf1f1/v1/Ganrich-Tekstil-Urun-Pasaportu-TR.pdf', 'Ganrich-Tekstil-Urun-Pasaportu-TR.pdf', 'bcbcd9282d25f5407974187031f4b0beb2a2f65e3033be08034cdbb48e9337c3', 272944, 'furkangul@ganrichadvisory.com', '2026-10-26T08:00:00.000Z', 'current');
